package luna.tools;
import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;
public class CastPathEquivalence {
 static List<AbstractInsnNode> path(ClassNode c,int lo,int hi){for(MethodNode m:c.methods)if(m.desc.equals("(I)V")){List<AbstractInsnNode>a=new ArrayList<AbstractInsnNode>();int n=0;for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()>=0){if(n>=lo&&n<=hi)a.add(i);n++;}return a;}throw new IllegalStateException();}
 static String shape(String d){return d.replaceAll("L[^;]+;","Lobject;");}
 public static void main(String[] a)throws Exception{JarFile rj=new JarFile(a[0]),hj=new JarFile(a[1]);ClassNode r=CombatCadencePatcher.discover(rj),h=CombatCadencePatcher.discover(hj);List<AbstractInsnNode>rp=path(r,275,341),hp=path(h,28,85);for(int i=337;i>=329;i--)rp.remove(i-275);if(rp.size()!=hp.size())throw new IllegalStateException("size");Map<String,String>map=new LinkedHashMap<String,String>();for(int i=0;i<rp.size();i++){AbstractInsnNode ri=rp.get(i),hi=hp.get(i);if(ri.getOpcode()!=hi.getOpcode())throw new IllegalStateException("opcode "+i);String rk=null,hk=null;if(ri instanceof FieldInsnNode){FieldInsnNode rf=(FieldInsnNode)ri,hf=(FieldInsnNode)hi;if(!shape(rf.desc).equals(shape(hf.desc)))throw new IllegalStateException("field desc");rk=rf.owner+"."+rf.name+" "+rf.desc;hk=hf.owner+"."+hf.name+" "+hf.desc;}else if(ri instanceof MethodInsnNode){MethodInsnNode rf=(MethodInsnNode)ri,hf=(MethodInsnNode)hi;if(!shape(rf.desc).equals(shape(hf.desc)))throw new IllegalStateException("method desc");rk=rf.owner+"."+rf.name+rf.desc;hk=hf.owner+"."+hf.name+hf.desc;}else if(ri instanceof VarInsnNode){if(((VarInsnNode)ri).var!=((VarInsnNode)hi).var)throw new IllegalStateException("var");}else if(ri instanceof IntInsnNode){if(((IntInsnNode)ri).operand!=((IntInsnNode)hi).operand)throw new IllegalStateException("int");}if(rk!=null){if(map.containsKey(rk)&&!map.get(rk).equals(hk))throw new IllegalStateException("inconsistent mapping");map.put(rk,hk);}}
 System.out.println("PASS 58 executable instructions identical opcodes, operand constants, local indexes, descriptor shapes; stable owner+member mapping.");System.out.println("Reference excluded329..337: Java class-literal lazy cache artifact inserted before actor direction PUTFIELD; has no actor/cast mutation.");for(Map.Entry<String,String>e:map.entrySet())System.out.println(e.getKey()+" => "+e.getValue());rj.close();hj.close();}
}
